import re, joblib, numpy as np, pandas as pd
def prompt_features(prompt):
    s='' if pd.isna(prompt) else str(prompt); n=max(len(s),1); words=re.findall(r"\b\w+\b",s)
    return {'prompt_char_len':len(s),'prompt_word_count':len(words),'prompt_line_count':s.count('\n')+1,'newline_count':s.count('\n'),'bullet_count':len(re.findall(r'(?m)^\s*(?:[-*•]|\d+[.)])\s+',s)),'question_mark_count':s.count('?'),'number_count':len(re.findall(r'\b\d+(?:\.\d+)?\b',s)),'code_block_count':s.count('```'),'has_code':int(bool(re.search(r'```|def |class |import |#include|SELECT |function ',s,re.I))),'has_json_or_schema':int(bool(re.search(r'JSON|schema|\{.*\}',s,re.I|re.S))),'has_table_like_format':int(bool(re.search(r'\|.*\|',s))),'has_math_expression':int(bool(re.search(r'\\[a-zA-Z]+|[=+\-*/^]|∑|√|≤|≥',s))),'has_stepwise_instruction':int(bool(re.search(r'step[- ]by[- ]step|\bstep\s*\d+\b|\bfirst\b.*\bthen\b',s,re.I|re.S))),'constraint_count_estimate':len(re.findall(r'\b(?:must|should|exactly|only|limit|format|constraint|require)\b',s,re.I)),'digit_ratio':sum(c.isdigit() for c in s)/n,'punctuation_ratio':sum((not c.isalnum()) and (not c.isspace()) for c in s)/n,'whitespace_ratio':sum(c.isspace() for c in s)/n,'uppercase_ratio':sum(c.isupper() for c in s)/n,'non_ascii_ratio':sum(ord(c)>127 for c in s)/n,'avg_word_length':np.mean([len(w) for w in words]) if words else 0.0}
